import{c as n,ao as e,ah as t,L as l,O as h,I as i,Q as p,aY as k,P as d}from"./chunks/framework.YKVbmyBD.js";const C=JSON.parse('{"title":"Linux 如何搭建网站","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/web-guide/web-release.md","filePath":"fovlin-notes/web-guide/web-release.md"}'),r={name:"fovlin-notes/web-guide/web-release.md"};function g(o,s,c,b,F,u){const a=e("center");return t(),l("div",null,[s[1]||(s[1]=h(`<h1 id="linux-如何搭建网站" tabindex="-1">Linux 如何搭建网站 <a class="header-anchor" href="#linux-如何搭建网站" aria-label="Permalink to “Linux 如何搭建网站”">​</a></h1><p>本文假设你已经了解前端基础，并已经制作了网页，想要将其部署在服务器上。</p><h2 id="web-服务器软件" tabindex="-1">Web 服务器软件 <a class="header-anchor" href="#web-服务器软件" aria-label="Permalink to “Web 服务器软件”">​</a></h2><p>Web 服务器是运行在 Linux 上的程序，它监听客户端的 HTTP 请求，然后返回相应的 HTML 文件和资源。</p><h3 id="常见的-web-服务器" tabindex="-1">常见的 Web 服务器 <a class="header-anchor" href="#常见的-web-服务器" aria-label="Permalink to “常见的 Web 服务器”">​</a></h3><table tabindex="0"><thead><tr><th>服务器</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Nginx</strong></td><td>轻量级、高性能、反向代理能力强</td><td>高流量网站、反向代理</td></tr><tr><td><strong>Apache</strong></td><td>功能全面、配置灵活、插件丰富</td><td>传统网站、需要多模块支持</td></tr><tr><td><strong>Caddy</strong></td><td>自动HTTPS、配置简单、现代化</td><td>小型网站、快速部署</td></tr></tbody></table><p>本文将围绕 Linux 上部署 Nginx 展开。</p><h2 id="安装-nginx" tabindex="-1">安装 Nginx <a class="header-anchor" href="#安装-nginx" aria-label="Permalink to “安装 Nginx”">​</a></h2><p>前往 Nginx 官方获取下载链接，对于 Linux 服务器，使用 wget 命令下载。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://nginx.org/download/nginx-1.30.0.tar.gz</span></span></code></pre></div><p>对安装包进行解压。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx-1.30.0.tar.gz</span></span></code></pre></div><p>前往该目录。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx-1.30.0</span></span></code></pre></div><p>根据 <code>README.md</code> 文件提示，安装依赖项。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libpcre3-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zlib1g-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gcc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><p>可以查看 Nginx 官方文档来查找自己需要添加的编译选项，例如要添加能够对 tcp/udp 协议进行管理的 Stream 模块，配置编译选项：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./configure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with-stream</span></span></code></pre></div><p>关于完整的编译配置选项（按需可选）：</p><p>其他的编译选项可以阅读官方文档。</p><p>接下来就是编译安装，使用如下命令编译并安装。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>安装完成后，默认会被安装在 <code>/usr/local/nginx</code> 目录下，前提是你没有通过 configure 更改安装目录。</p><p>为 nginx 创建软链接，方便随时使用 nginx。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/nginx/sbin/nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/nginx</span></span></code></pre></div><p>然后运行此命令验证安装。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h3 id="启动和管理-nginx" tabindex="-1">启动和管理 Nginx <a class="header-anchor" href="#启动和管理-nginx" aria-label="Permalink to “启动和管理 Nginx”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动 Nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/sbin/nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重新加载配置（重启 Nginx）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/sbin/nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 优雅关闭</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/sbin/nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quit</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 强制关闭</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/sbin/nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><h3 id="基本配置" tabindex="-1">基本配置 <a class="header-anchor" href="#基本配置" aria-label="Permalink to “基本配置”">​</a></h3><p>编译安装的 Nginx 的主配置文件位于 <code>/usr/local/nginx/conf/nginx.conf</code>。</p><p>配置后使用以下命令重新加载 nginx</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><h4 id="简单的网站配置示例" tabindex="-1">简单的网站配置示例 <a class="header-anchor" href="#简单的网站配置示例" aria-label="Permalink to “简单的网站配置示例”">​</a></h4><p>在 <code>/usr/local/nginx/conf/nginx.conf</code> 的 <code>http {}</code> 块中编辑以下内容：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen 80;</span></span>
<span class="line"><span>    server_name example.com www.example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 网站根目录，网站源代码放置在此处。</span></span>
<span class="line"><span>        root /home/web;</span></span>
<span class="line"><span>        index index.html index.htm;</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 错误页面</span></span>
<span class="line"><span>    error_page 404 /404.html;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如想要配置 SSL 证书，可借助 certbot 工具进行配置，但前提条件是你的 Nginx 配置文件位于 <code>/etc/nginx/nginx.conf</code>。</p><p>但默认编译安装的配置文件位于 <code>/usr/local/nginx/conf/nginx.conf</code>，所以你可以选择创建软链接到此处。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/nginx/conf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx</span></span></code></pre></div><p>随后将网站文件部署到其中即可，关于更多的 Nginx 配置，可阅读下一页。</p><br><br><br>`,43)),i("p",null,[i("em",null,[i("strong",null,[p(a,null,{default:k(()=>[...s[0]||(s[0]=[d("--- 由 柏茯灵_RsDline 编写 ---",-1)])]),_:1})])])])])}const x=n(r,[["render",g]]);export{C as __pageData,x as default};
